<?php
/** Quetta Workbench administrator register: find and export minimal dashboard-summary export accountability events, never exported values. */
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';
require_once __DIR__ . '/../includes/workspace.php';
require_once __DIR__ . '/../includes/dashboard-export-audits.php';

require_role(['admin']);
$filters = dashboard_summary_export_audit_filters($_GET);
$roles = dashboard_summary_export_audit_roles();
$eventRanges = dashboard_summary_export_audit_event_ranges();
$sorts = dashboard_summary_export_audit_sorts();
$pageSize = 25;
$total = dashboard_summary_export_audit_count($filters);
$totalPages = max(1, (int) ceil($total / $pageSize));
$page = min($filters['page'], $totalPages);
$filters['page'] = $page;
$records = dashboard_summary_export_audit_rows($filters, $pageSize, ($page - 1) * $pageSize);
$query = dashboard_summary_export_audit_query($filters);
$pageUrl = static fn (array $overrides): string => app_url('admin/dashboard-export-audit.php' . (($nextQuery = dashboard_summary_export_audit_query($filters, $overrides)) !== '' ? '?' . $nextQuery : ''));
$sortUrl = static fn (string $sort): string => $pageUrl(['sort' => $sort, 'page' => 1]);
$nextSort = static fn (string $prefix, string $initial): string => str_starts_with($filters['sort'], $prefix) ? $sorts[$filters['sort']]['next'] : $initial;
$sortIndicator = static fn (string $key): string => ($filters['sort'] === $key ? ($sorts[$key]['direction'] === 'ascending' ? ' ↑' : ' ↓') : ' ↕');
workspace_open('Dashboard export audit', 'dashboard_export_audit');
?>
<section class="workspace-section"><div class="workspace-section-header"><div><h2>Dashboard summary exports</h2><p>Find accountable export events by account, role, export time, or selected summary period. This register and its CSV never display exported values.</p></div><div class="workspace-section-actions"><span class="status-pill"><?= $total ?> matching exports</span><a class="button button-quiet" href="<?= e(app_url('admin/dashboard-export-audit-export.php' . ($query !== '' ? '?' . $query : ''))) ?>">Export filtered CSV</a></div></div><form class="activity-date-filter audit-filter-form" method="get"><label>Account<input name="account" value="<?= e($filters['account']) ?>" maxlength="80" placeholder="Account name"></label><label>Role<select name="role"><option value="">All roles</option><?php foreach ($roles as $slug => $label): ?><option value="<?= e($slug) ?>" <?= $filters['role'] === $slug ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><fieldset class="audit-date-range"><legend>Export event date range</legend><label>From<input type="date" name="exported_from" value="<?= e($filters['exported_from']?->format('Y-m-d') ?? '') ?>"></label><label>To<input type="date" name="exported_to" value="<?= e($filters['exported_to']?->format('Y-m-d') ?? '') ?>"></label><div class="audit-range-presets"><span>Quick range</span><?php foreach ($eventRanges as $value => $label): ?><button class="button button-outline <?= $filters['event_range'] === $value ? 'is-active' : '' ?>" type="submit" name="event_range" value="<?= e($value) ?>" <?= $filters['event_range'] === $value ? 'aria-current="true"' : '' ?>><?= e($label) ?></button><?php endforeach; ?></div></fieldset><fieldset class="audit-date-range"><legend>Selected summary range</legend><label>From<input type="date" name="summary_from" value="<?= e($filters['summary_from']?->format('Y-m-d') ?? '') ?>"></label><label>To<input type="date" name="summary_to" value="<?= e($filters['summary_to']?->format('Y-m-d') ?? '') ?>"></label></fieldset><input type="hidden" name="sort" value="<?= e($filters['sort']) ?>"><button class="button button-quiet" type="submit">Filter exports</button><a href="<?= e(app_url('admin/dashboard-export-audit.php')) ?>">Clear filters</a></form><div class="data-table-wrap"><table class="data-table"><thead><tr><th aria-sort="<?= $filters['sort'] === 'account_asc' ? 'ascending' : ($filters['sort'] === 'account_desc' ? 'descending' : 'none') ?>"><a class="audit-table-sort" href="<?= e($sortUrl($nextSort('account_', 'account_asc'))) ?>">Account<span aria-hidden="true"><?= e($sortIndicator(str_starts_with($filters['sort'], 'account_') ? $filters['sort'] : '')) ?></span></a></th><th aria-sort="<?= $filters['sort'] === 'role_asc' ? 'ascending' : ($filters['sort'] === 'role_desc' ? 'descending' : 'none') ?>"><a class="audit-table-sort" href="<?= e($sortUrl($nextSort('role_', 'role_asc'))) ?>">Role at export<span aria-hidden="true"><?= e($sortIndicator(str_starts_with($filters['sort'], 'role_') ? $filters['sort'] : '')) ?></span></a></th><th aria-sort="<?= $filters['sort'] === 'summary_start_asc' ? 'ascending' : ($filters['sort'] === 'summary_start_desc' ? 'descending' : 'none') ?>"><a class="audit-table-sort" href="<?= e($sortUrl($nextSort('summary_start_', 'summary_start_asc'))) ?>">Selected summary period<span aria-hidden="true"><?= e($sortIndicator(str_starts_with($filters['sort'], 'summary_start_') ? $filters['sort'] : '')) ?></span></a></th><th aria-sort="<?= $filters['sort'] === 'exported_at_asc' ? 'ascending' : ($filters['sort'] === 'exported_at_desc' ? 'descending' : 'none') ?>"><a class="audit-table-sort" href="<?= e($sortUrl($nextSort('exported_at_', 'exported_at_asc'))) ?>">Exported<span aria-hidden="true"><?= e($sortIndicator(str_starts_with($filters['sort'], 'exported_at_') ? $filters['sort'] : '')) ?></span></a></th></tr></thead><tbody><?php if ($records === []): ?><tr><td colspan="4">No dashboard-summary exports match these filters.</td></tr><?php else: foreach ($records as $record): ?><tr><td><strong><?= e($record['actor_name']) ?></strong><br><span class="muted">Account #<?= (int) $record['actor_user_id'] ?></span></td><td><?= e($roles[$record['exported_role']] ?? 'Unavailable role') ?></td><td><?= e(($record['period_start'] ?? '') !== '' ? date('j M Y', strtotime((string) $record['period_start'])) : 'Unavailable') ?> to <?= e(($record['period_end'] ?? '') !== '' ? date('j M Y', strtotime((string) $record['period_end'])) : 'Unavailable') ?></td><td><?= e(date('j M Y H:i', strtotime((string) $record['created_at']))) ?></td></tr><?php endforeach; endif; ?></tbody></table></div><?php if ($total > 0): ?><nav class="audit-pagination" aria-label="Dashboard export audit pages"><span><?= $total ?> matching exports · Page <?= $page ?> of <?= $totalPages ?></span><div><?php if ($page > 1): ?><a class="button button-outline" href="<?= e($pageUrl(['page' => $page - 1])) ?>">Previous</a><?php endif; ?><?php if ($page < $totalPages): ?><a class="button button-quiet" href="<?= e($pageUrl(['page' => $page + 1])) ?>">Next</a><?php endif; ?></div></nav><?php endif; ?></section>
<?php workspace_close(); ?>
